import{_ as s,a0 as i,w as n,s as p,I as l,x as t,a1 as r,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"strace 可以解決什麼問題？ | LCTT x X-CMD","titleTemplate":false,"description":"strace 可以解決什麼問題？ | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"strace 可以解決什麼問題？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"strace 可以解決什麼問題？ | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210403 What problems do people solve with strace","title":"strace 可以解決什麼問題？","tag":"202104","desc":""},"relativePath":"202104/20210403 What problems do people solve with strace.md","filePath":"[post].md"}'),u={name:"202104/20210403 What problems do people solve with strace.md"};function m(f,e,b,h,c,T){const o=i("Link");return n(),p("div",null,[e[36]||(e[36]=l("h1",{id:"strace-可以解決什麼問題",tabindex:"-1"},[t("strace 可以解決什麼問題？ "),l("a",{class:"header-anchor",href:"#strace-可以解決什麼問題","aria-label":"Permalink to “strace 可以解決什麼問題？”"},"​")],-1)),e[37]||(e[37]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/05/094825y66126r56z361rz1.jpg",alt:""})],-1)),l("p",null,[e[1]||(e[1]=t("昨天我 ",-1)),r(o,{href:"https://twitter.com/b0rk/status/1378014888405168132"},{default:a(()=>[...e[0]||(e[0]=[t("在 Twitter 上詢問大家用 strace 解決了什麼問題？",-1)])]),_:1}),e[2]||(e[2]=t("，和往常一樣，大家真的是給出了自己的答案! 我收到了大約 200 個答案，然後花了很多時間手動將它們歸為 9 類。",-1))]),e[38]||(e[38]=l("p",null,[t("這些解決的問題都是關於尋找程序依賴的文件、找出程序卡住或慢的原因、或者找出程序失敗的原因。這些總體上與我自己使用 "),l("code",null,"strace"),t(" 的內容相吻合，但也有一些我沒有想到的東西!")],-1)),l("p",null,[e[6]||(e[6]=t("我不打算在這篇文章裏解釋什麼是 ",-1)),e[7]||(e[7]=l("code",null,"strace",-1)),e[8]||(e[8]=t("，但我有一本 ",-1)),r(o,{href:"https://wizardzines.com/zines/strace"},{default:a(()=>[...e[3]||(e[3]=[t("關於它的免費雜誌",-1)])]),_:1}),e[9]||(e[9]=t(" 和 ",-1)),r(o,{href:"https://www.youtube.com/watch?v=4pEHfGKB-OE"},{default:a(()=>[...e[4]||(e[4]=[t("一個講座",-1)])]),_:1}),e[10]||(e[10]=t(" 以及 ",-1)),r(o,{href:"https://jvns.ca/categories/strace"},{default:a(()=>[...e[5]||(e[5]=[t("很多博文",-1)])]),_:1}),e[11]||(e[11]=t("。",-1))]),e[39]||(e[39]=d('<h3 id="問題-1-配置文件在哪裏" tabindex="-1">問題 1：配置文件在哪裏？ <a class="header-anchor" href="#問題-1-配置文件在哪裏" aria-label="Permalink to “問題 1：配置文件在哪裏？”">​</a></h3><p>最受歡迎的問題是“這個程序有一個配置文件，但我不知道它在哪裏”。這可能也是我最常使用 <code>strace</code> 解決的問題，因為這是個很簡單的問題。</p><p>這很好，因為一個程序有一百萬種方法來記錄它的配置文件在哪裏（在手冊頁、網站上、<code>--help</code>等），但只有一種方法可以讓它真正打開它（用系統調用！）。</p><h3 id="問題-2-這個程序還依賴什麼文件" tabindex="-1">問題 2：這個程序還依賴什麼文件？ <a class="header-anchor" href="#問題-2-這個程序還依賴什麼文件" aria-label="Permalink to “問題 2：這個程序還依賴什麼文件？”">​</a></h3><p>你也可以使用 <code>strace</code> 來查找程序依賴的其他類型的文件，比如：</p>',5)),l("ul",null,[l("li",null,[e[13]||(e[13]=t("動態鏈接庫（“為什麼我的程序加載了這個錯誤版本的 ",-1)),e[14]||(e[14]=l("code",null,".so",-1)),e[15]||(e[15]=t(' 文件？"），比如 ',-1)),r(o,{href:"https://jvns.ca/blog/2014/03/10/debugging-shared-library-problems-with-strace/"},{default:a(()=>[...e[12]||(e[12]=[t("我在 2014 年調試的這個 ruby 問題",-1)])]),_:1})]),e[17]||(e[17]=l("li",null,"它在哪裏尋找它的 Ruby gem（Ruby 出現了幾次這種情況！）",-1)),e[18]||(e[18]=l("li",null,"SSL 根證書",-1)),e[19]||(e[19]=l("li",null,"遊戲的存檔文件",-1)),e[20]||(e[20]=l("li",null,"一個閉源程序的數據文件",-1)),l("li",null,[r(o,{href:"https://indexandmain.com/post/shrink-node-modules-with-refining"},{default:a(()=>[...e[16]||(e[16]=[t("哪些 node_modules 文件沒有被使用",-1)])]),_:1})])]),e[40]||(e[40]=d('<h3 id="問題-3-為什麼這個程序會掛掉" tabindex="-1">問題 3：為什麼這個程序會掛掉？ <a class="header-anchor" href="#問題-3-為什麼這個程序會掛掉" aria-label="Permalink to “問題 3：為什麼這個程序會掛掉？”">​</a></h3><p>你有一個程序，它只是坐在那裏什麼都不做，這是怎麼回事？這個問題特別容易回答，因為很多時候你只需要運行 <code>strace -p PID</code>，看看當前運行的是什麼系統調用。你甚至不需要看幾百行的輸出。</p><p>答案通常是“正在等待某種 I/O”。“為什麼會卡住”的一些可能的答案（雖然還有很多！）：</p><ul><li>它一直在輪詢 <code>select()</code></li><li>正在 <code>wait()</code> 等待一個子進程完成</li><li>它在向某個沒有響應的東西發出網絡請求</li><li>正在進行 <code>write()</code>，但由於緩衝區已滿而被阻止。</li><li>它在 stdin 上做 <code>read()</code>，等待輸入。</li></ul><p>有人還舉了一個很好的例子，用 <code>strace</code> 調試一個卡住的 <code>df</code> 命令：“用 <code>strace df -h</code> 你可以找到卡住的掛載，然後卸載它”。</p><h3 id="問題-4-這個程序卡住了嗎" tabindex="-1">問題 4：這個程序卡住了嗎？ <a class="header-anchor" href="#問題-4-這個程序卡住了嗎" aria-label="Permalink to “問題 4：這個程序卡住了嗎？”">​</a></h3><p>這是上一個問題的變種：有時一個程序運行的時間比你預期的要長，你只是想知道它是否卡住了，或者它是否還在繼續進行。</p><p>只要程序在運行過程中進行系統調用，用 <code>strace</code> 就可以超簡單地回答這個問題：只需 <code>strace</code> 它，看看它是否在進行新的系統調用!</p><h3 id="問題-5-為什麼這個程序很慢" tabindex="-1">問題 5：為什麼這個程序很慢？ <a class="header-anchor" href="#問題-5-為什麼這個程序很慢" aria-label="Permalink to “問題 5：為什麼這個程序很慢？”">​</a></h3><p>你可以使用 <code>strace</code> 作為一種粗略的剖析工具：<code>strace -t</code> 會顯示每次系統調用的時間戳，這樣你就可以尋找大的漏洞，找到罪魁禍首。</p><p>以下是 Twitter 上 9 個人使用 <code>strace</code> 調試“為什麼這個程序很慢？”的小故事。</p><ul><li>早在 2000 年，我幫助支持的一個基於 Java 的網站在適度的負載下奄奄一息：頁面加載緩慢，甚至完全加載不出來。我們對 J2EE 應用服務器進行了測試，發現它每次只讀取一個類文件。開發人員沒有使用 BufferedReader，這是典型的 Java 錯誤。</li><li>優化應用程序的啓動時間……運行 <code>strace</code> 可以讓人大開眼界，因為有大量不必要的文件系統交互在進行（例如，在同一個配置文件上反覆打開/讀取/關閉；在一個緩慢的 NFS 掛載上加載大量的字體文件，等等）。</li><li>問自己為什麼在 PHP 中從會話文件中讀取（通常是小於 100 字節）非常慢。結果發現一些 <code>flock</code> 系統調用花了大約 60 秒。</li><li>一個程序表現得異常緩慢。使用 <code>strace</code> 找出它在每次請求時，通過從 <code>/dev/random</code> 讀取數據並耗盡熵來重新初始化其內部偽隨機數發生器。</li><li>我記得最近一件事是連接到一個任務處理程序，看到它有多少網絡調用（這是意想不到的）。</li><li><code>strace</code> 顯示它打開/讀取同一個配置文件數千次。</li><li>服務器隨機使用 100% 的 CPU 時間，實際流量很低。原來是碰到打開文件數限制，接受一個套接字時，得到 EMFILE 錯誤而沒有報告，然後一直重試。</li><li>一個工作流運行超慢，但是沒有日誌，結果它做一個 POST 請求花了 30 秒而超時，然後重試了 5 次……結果後台服務不堪重負，但是也沒有可視性。</li><li>使用 <code>strace</code> 注意到 <code>gethostbyname()</code> 需要很長時間才能返回（你不能直接看到 <code>gethostbyname</code>，但你可以看到 <code>strace</code> 中的 DNS 數據包）</li></ul><h3 id="問題-6-隱藏的權限錯誤" tabindex="-1">問題 6：隱藏的權限錯誤 <a class="header-anchor" href="#問題-6-隱藏的權限錯誤" aria-label="Permalink to “問題 6：隱藏的權限錯誤”">​</a></h3><p>有時候程序因為一個神秘的原因而失敗，但問題只是有一些它沒有權限打開的文件。在理想的世界裏，程序會報告這些錯誤（“Error opening file /dev/whatever: permission denied”），當然這個世界並不完美，所以 <code>strace</code> 真的可以幫助解決這個問題!</p><p>這其實是我最近使用 <code>strace</code> 做的事情。我使用了一台 AxiDraw 繪圖儀，當我試圖啓動它時，它打印出了一個難以理解的錯誤信息。我 <code>strace</code> 它，結果發現我的用户沒有權限打開 USB 設備。</p><h3 id="問題-7-正在使用什麼命令列參數" tabindex="-1">問題 7：正在使用什麼命令列參數？ <a class="header-anchor" href="#問題-7-正在使用什麼命令列參數" aria-label="Permalink to “問題 7：正在使用什麼命令列參數？”">​</a></h3><p>有時候，一個腳本正在運行另一個程序，你想知道它傳遞的是什麼命令列標誌！</p><p>幾個來自 Twitter 的例子。</p><ul><li>找出實際上是用來編譯代碼的編譯器標誌</li><li>由於命令列太長，命令失敗了</li></ul><h3 id="問題-8-為什麼這個網絡連接失敗" tabindex="-1">問題 8：為什麼這個網絡連接失敗？ <a class="header-anchor" href="#問題-8-為什麼這個網絡連接失敗" aria-label="Permalink to “問題 8：為什麼這個網絡連接失敗？”">​</a></h3><p>基本上，這裏的目標是找到網絡連接的域名 / IP 地址。你可以通過 DNS 請求來查找域名，或者通過 <code>connect</code> 系統調用來查找 IP。</p><p>一般來説，當 <code>tcpdump</code> 因為某些原因不能使用或者只是因為比較熟悉 <code>strace</code> 時，就經常會使用 <code>strace</code> 調試網絡問題。</p><h3 id="問題-9-為什麼這個程序以一種方式運行時成功-以另一種方式運行時失敗" tabindex="-1">問題 9：為什麼這個程序以一種方式運行時成功，以另一種方式運行時失敗？ <a class="header-anchor" href="#問題-9-為什麼這個程序以一種方式運行時成功-以另一種方式運行時失敗" aria-label="Permalink to “問題 9：為什麼這個程序以一種方式運行時成功，以另一種方式運行時失敗？”">​</a></h3><p>例如：</p><ul><li>同樣的二進制程序在一台機器上可以運行，在另一台機器上卻失敗了</li><li>可以運行，但被 systemd 單元文件生成時失敗</li><li>可以運行，但以 <code>su - user /some/script</code> 的方式運行時失敗</li><li>可以運行，作為 cron 作業運行時失敗</li></ul><p>能夠比較兩種情況下的 <code>strace</code> 輸出是非常有用的。雖然我在調試“以我的用户身份工作，而在同一台計算機上以不同方式運行時卻失敗了”時，第一步是“看看我的環境變量”。</p><h3 id="我在做什麼-慢慢地建立一些挑戰" tabindex="-1">我在做什麼：慢慢地建立一些挑戰 <a class="header-anchor" href="#我在做什麼-慢慢地建立一些挑戰" aria-label="Permalink to “我在做什麼：慢慢地建立一些挑戰”">​</a></h3><p>我之所以會想到這個問題，是因為我一直在慢慢地進行一些挑戰，以幫助人們練習使用 <code>strace</code> 和其他命令列工具。我的想法是，給你一個問題，一個終端，你可以自由地以任何方式解決它。</p><p>所以我的目標是用它來建立一些你可以用 <code>strace</code> 解決的練習題，這些練習題反映了人們在現實生活中實際使用它解決的問題。</p><h3 id="就是這樣" tabindex="-1">就是這樣! <a class="header-anchor" href="#就是這樣" aria-label="Permalink to “就是這樣!”">​</a></h3><p>可能還有更多的問題可以用 <code>strace</code> 解決，我在這裏還沒有講到，我很樂意聽到我錯過了什麼!</p><p>我真的很喜歡看到很多相同的用法一次又一次地出現：至少有 20 個不同的人回答説他們使用 <code>strace</code> 來查找配置文件。而且和以往一樣，我覺得這樣一個簡單的工具（“跟蹤系統調用！”）可以用來解決這麼多不同類型的問題，真的很令人高興。</p><hr>',33)),l("p",null,[e[22]||(e[22]=t("via: ",-1)),r(o,{href:"https://jvns.ca/blog/2021/04/03/what-problems-do-people-solve-with-strace/"},{default:a(()=>[...e[21]||(e[21]=[t("https://jvns.ca/blog/2021/04/03/what-problems-do-people-solve-with-strace/",-1)])]),_:1})]),l("p",null,[e[27]||(e[27]=t("作者：",-1)),r(o,{href:"https://jvns.ca/"},{default:a(()=>[...e[23]||(e[23]=[t("Julia Evans",-1)])]),_:1}),e[28]||(e[28]=t(" 選題：",-1)),r(o,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[24]||(e[24]=[t("lujun9972",-1)])]),_:1}),e[29]||(e[29]=t(" 譯者：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[25]||(e[25]=[t("wxy",-1)])]),_:1}),e[30]||(e[30]=t(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:a(()=>[...e[26]||(e[26]=[t("wxy",-1)])]),_:1})]),l("p",null,[e[33]||(e[33]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[31]||(e[31]=[t("LCTT",-1)])]),_:1}),e[34]||(e[34]=t(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:a(()=>[...e[32]||(e[32]=[t("Linux中國",-1)])]),_:1}),e[35]||(e[35]=t(" 榮譽推出",-1))])])}const g=s(u,[["render",m]]);export{P as __pageData,g as default};
